struct V{uint64_t w[3];}; inline V addv(const V&a,const V&b){return V{{a.w[0]+b.w[0],a.w[1]+b.w[1],a.w[2]+b.w[2]}};} inline bool eqv(const V&a,const V&b){return a.w[0]==b.w[0]&&a.w[1]==b.w[1]&&a.w[2]==b.w[2];}
inline uint64_t hv(const V&a){uint64_t h=0x9e3779b97f4a7c15ULL;for(int k=0;k<3;k++){uint64_t x=a.w[k]+0x9e3779b97f4a7c15ULL+(h<<6)+(h>>2);x^=x>>30;x*=0xbf58476d1ce4e5b9ULL;x^=x>>27;x*=0x94d049bb133111ebULL;x^=x>>31;h^=x;}return h;} struct Rec{uint64_t h;uint32_t code;};inline uint32_t code3(int a,int b,int c){return (uint32_t)a|((uint32_t)b<<10)|((uint32_t)c<<20);}inline void dec3(uint32_t z,int&a,int&b,int&c){a=z&1023;b=(z>>10)&1023;c=(z>>20)&1023;}
int main(int argc,char**argv){if(argc!=3)return 2;string s;{ifstream f(argv[1]);s.assign((istreambuf_iterator<char>(f)),{});}vector<array<int,45>>raw;size_t p=0;while((p=s.find("\"vector\":[",p))!=string::npos){p+=10;array<int,45>a{};for(int q=0;q<45;q++){a[q]=stoi(s.substr(p));p=s.find(q==44?']':',',p)+1;}raw.push_back(a);}if(raw.size()!=720)return 3;vector<int>old={90,206,290,99,373,415,554,610,640},out;array<char,720>io{};for(int x:old)io[x]=1;for(int i=0;i<720;i++)if(!io[i])out.push_back(i);int n=out.size();vector<V>v(n);for(int ii=0;ii<n;ii++){V z{{0,0,0}};for(int q=0;q<45;q++)z.w[q/16]|=(uint64_t)raw[out[ii]][q]<<(4*(q%16));v[ii]=z;}uint64_t nt=(uint64_t)n*(n-1)*(n-2)/6;vector<Rec>T;T.reserve(nt);for(int a=0;a<n;a++)for(int b=a+1;b<n;b++){V ab=addv(v[a],v[b]);for(int c=b+1;c<n;c++){V z=addv(ab,v[c]);T.push_back({hv(z),code3(a,b,c)});}}sort(T.begin(),T.end(),[](auto&a,auto&b){return a.h<b.h;});set<array<int,9>>tuples;int feasible_targets=0;uint64_t hashhits=0,verified=0;
for(int a=0;a<9;a++)for(int b=a+1;b<9;b++)for(int c=b+1;c<9;c++)for(int d=c+1;d<9;d++)for(int e=d+1;e<9;e++){vector<int>rem={old[a],old[b],old[c],old[d],old[e]};array<int,45>target{};for(int x:rem)for(int q=0;q<45;q++)target[q]+=raw[x][q];bool targetyes=false;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++){V comp{{0,0,0}};bool ok=true;for(int q=0;q<45;q++){int x=target[q]-raw[out[i]][q]-raw[out[j]][q];if(x<0||x>12){ok=false;break;}comp.w[q/16]|=(uint64_t)x<<(4*(q%16));}if(!ok)continue;uint64_t h=hv(comp);auto lo=lower_bound(T.begin(),T.end(),h,[](auto const&r,uint64_t x){return r.h<x;});auto hi=upper_bound(T.begin(),T.end(),h,[](uint64_t x,auto const&r){return x<r.h;});hashhits+=hi-lo;for(auto it=lo;it!=hi;++it){int x,y,z;dec3(it->code,x,y,z);if(x==i||x==j||y==i||y==j||z==i||z==j)continue;V tv=addv(addv(v[x],v[y]),v[z]);if(!eqv(tv,comp))continue;verified++;vector<int>add={out[i],out[j],out[x],out[y],out[z]};sort(add.begin(),add.end());vector<int>all;for(int u:old)if(find(rem.begin(),rem.end(),u)==rem.end())all.push_back(u);all.insert(all.end(),add.begin(),add.end());sort(all.begin(),all.end());if(all.size()!=9||unique(all.begin(),all.end())!=all.end())continue;array<int,9>tup{};copy(all.begin(),all.end(),tup.begin());tuples.insert(tup);targetyes=true;}}if(targetyes)feasible_targets++;}
ofstream o(argv[2]);o<<"{\"outside_signatures\":"<<n<<",\"triple_records\":"<<T.size()<<",\"removal_targets\":126,\"feasible_targets\":"<<feasible_targets<<",\"hash_hits\":"<<hashhits<<",\"verified_decompositions\":"<<verified<<",\"unique_radius5_tuples\":"<<tuples.size()<<",\"tuples\":[";bool f=1;for(auto&t:tuples){if(!f)o<<",";f=0;o<<"[";for(int i=0;i<9;i++){if(i)o<<",";o<<t[i];}o<<"]";}o<<"]}\n";}
